package com.x.myview.ui.components

// GENERATED FILE - exercise pose data (side/front view stick-figure keyframes).
// Each frame = 11 points (x,y) * 1000 : head, neck, hip, elbowN, handN, elbowF, handF, kneeN, footN, kneeF, footF
// World units: x right, y up, ground at y = 0.

class ExAnim(
    val loopMs: Int,
    val w: Float,
    val h: Float,
    val frames: FloatArray,
    val props: FloatArray,
    val front: Boolean,
    val rope: Boolean,
    val mat: Boolean,
) {
    val count: Int get() = frames.size / 22
}

object ExerciseAnimData {
    private fun dec(s: String): FloatArray {
        if (s.isBlank()) return FloatArray(0)
        val p = s.trim().split(' ')
        return FloatArray(p.size) { p[it].toInt() / 1000f }
    }

    private val cache = HashMap<String, ExAnim>()

    fun get(key: String): ExAnim? {
        cache[key]?.let { return it }
        val a = build(key) ?: return null
        cache[key] = a
        return a
    }

